package org.marketreview.nativeapp;
import android.content.Context;import android.view.*;import android.widget.*;import java.io.File;import java.util.*;import org.json.*;
final class MaterialLibraryScreen extends LinearLayout {
 interface Sources{JSONArray current()throws Exception;}
 interface Work{void run()throws Exception;}
 LinearLayout readerHost;ScrollView editorScroll;boolean editing;
 final MaterialLibraryStore store;final Sources sources;final SourceHandoffPanel.Opener opener;final FrameLayout frame;final ScrollView main,reader,io;final LinearLayout rows;final TextView status,body,preview;final EditText search,category,tags,notes;final Spinner order;final Map<String,Spinner> filters=new LinkedHashMap<>();final Map<String,List<String>> options=new LinkedHashMap<>();final Map<String,String> selected=new LinkedHashMap<>();final Button previous,next;JSONArray all=new JSONArray(),matches=new JSONArray(),baselineTags=new JSONArray();JSONObject current=new JSONObject(),baseline=new JSONObject(),pending=new JSONObject(),heads=new JSONObject();String expected="",revision="";int page=0,view=0,orderSelected=0;boolean loading=true,dark;SourceHandoffPanel.Exporter exporter;Runnable chooseImport;
 MaterialLibraryScreen(Context c,File file,Sources sources,SourceHandoffPanel.Opener opener)throws Exception{super(c);setOrientation(VERTICAL);this.sources=sources;this.opener=opener;store=new MaterialLibraryStore(file);frame=new FrameLayout(c);addView(frame,new LayoutParams(-1,0,1));status=new TextView(c);addView(status);main=new ScrollView(c);LinearLayout ml=layout(main);TextView title=new TextView(c);title.setText("全量本机资料库 · 人工分类不代表证据事实或产业归属");ml.addView(title);search=new EditText(c);search.setHint("检索全部标题、完整正文、原标签与人工分类");ml.addView(search);String[] keys={"source","topic","type","category"},labels={"来源/作者","原主题","原资料类型","人工分类"};for(int i=0;i<keys.length;i++){String key=keys[i];TextView label=new TextView(c);label.setText(labels[i]);ml.addView(label);Spinner s=new Spinner(c);ml.addView(s);filters.put(key,s);options.put(key,new ArrayList<>());selected.put(key,"");s.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?>a){}public void onItemSelected(AdapterView<?>a,View v,int index,long id){if(!loading&&index==s.getSelectedItemPosition()){List<String> values=options.get(key);if(index>=0&&index<values.size()&&!values.get(index).equals(selected.get(key))){selected.put(key,values.get(index));page=0;guard(()->{render();persist();});}}}});}order=new Spinner(c);order.setAdapter(new ArrayAdapter<String>(c,android.R.layout.simple_spinner_dropdown_item,new String[]{"最新在前","最早在前"}));ml.addView(order);rows=new LinearLayout(c);rows.setOrientation(VERTICAL);ml.addView(rows);previous=button(ml,"上一页",()->{if(page>0)page--;render();persist();});next=button(ml,"下一页",()->{if((page+1)*20<matches.length())page++;render();persist();});button(ml,"重读全量资料",()->{refresh();persist();});reader=new ScrollView(c);LinearLayout rl=layout(reader);button(rl,"返回检索",()->{show(0);persist();});body=new TextView(c);body.setTextIsSelectable(true);rl.addView(body);category=new EditText(c);category.setHint("人工分类");rl.addView(category);tags=new EditText(c);tags.setHint("人工标签，用英文分号分隔");rl.addView(tags);notes=new EditText(c);notes.setHint("人工笔记");notes.setMinLines(3);rl.addView(notes);button(rl,"保存人工分类",()->{MaterialLibraryModel.require(current.length()>0,"先选资料");if(EvidenceReviewModel.canonical(fields()).equals(EvidenceReviewModel.canonical(baseline))){status.setText("分类未变化；未新增记录");return;}MaterialLibraryModel.resolve(current.getJSONObject("reference"),sourceRows());JSONObject r=MaterialLibraryModel.classification(current.getJSONObject("reference"),category.getText().toString(),tagArray(),notes.getText().toString(),expected);store.save(r,expected);expected=r.getString("id");baselineTags=r.getJSONArray("tags");baseline=fields();heads=store.heads();body.setText(MaterialLibraryModel.read(current,r));persist();status.setText("人工分类已保存；原文未修改");});button(rl,"放弃未保存分类",()->{loading=true;category.setText(baseline.optString("category"));tags.setText(baseline.optString("tagsText"));notes.setText(baseline.optString("notes"));loading=false;persist();});button(rl,"回到准确现有来源",()->{MaterialLibraryModel.require(opener!=null&&current.length()>0,"宿主未接来源入口或未选资料");JSONObject ref=current.getJSONObject("reference");opener.open(ref.getString("kind"),MaterialLibraryModel.resolve(ref,sourceRows()));});io=new ScrollView(c);LinearLayout il=layout(io);button(il,"返回检索",()->{show(0);persist();});preview=new TextView(c);preview.setTextIsSelectable(true);il.addView(preview);button(il,"确认分类导入（保留本机现有分类）",()->{MaterialLibraryModel.require(pending.length()>0,"没有已预览分类备份");store.merge(pending);pending=new JSONObject();heads=store.heads();persist();status.setText("已合并独立分类历史；现有分类及原文未覆盖");});button(il,"取消预览",()->{pending=new JSONObject();persist();show(0);});button(ml,"历史分类",()->{preview.setText(MaterialLibraryModel.json(new JSONObject().put("history",store.history())));show(2);});button(ml,"预览分类备份导入",()->{MaterialLibraryModel.require(chooseImport!=null,"宿主未接文件选择");chooseImport.run();});button(ml,"导出全部分类历史",()->{MaterialLibraryModel.require(exporter!=null,"宿主未接导出");exporter.write("material-library.json","application/json",store.backup().getBytes(java.nio.charset.StandardCharsets.UTF_8));status.setText("已交给文件选择，实际写入结果由宿主确认；不导出草稿");});refresh();JSONObject saved=store.state();revision=saved.optString("revision");restoreState(saved);loading=false;android.text.TextWatcher watcher=new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int d){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int d){if(!loading)persist();}};for(EditText edit:new EditText[]{category,tags,notes})edit.addTextChangedListener(watcher);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int d){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int d){if(!loading){page=0;guard(()->{render();persist();});}}});order.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?>a){}public void onItemSelected(AdapterView<?>a,View v,int index,long id){if(!loading&&index==order.getSelectedItemPosition()&&orderSelected!=index){orderSelected=index;page=0;guard(()->{render();persist();});}}});compactReader(rl,ml);show(view);setEditing(saved.optBoolean("editing"));}
 void compactReader(LinearLayout old,LinearLayout mainContent){
  // Keep full text in its own viewport; editing is an internal pane, not a dialog.
  readerHost=new LinearLayout(getContext());readerHost.setOrientation(VERTICAL);
  LinearLayout bar=new LinearLayout(getContext());readerHost.addView(bar,new LayoutParams(-1,dp(48)));
  Button back=action(bar,"检索","materialSearchBack",()->{show(0);persist();});
  action(bar,"正文","materialRead",()->{setEditing(false);persist();});
  action(bar,"分类 / 笔记","materialEdit",()->{setEditing(true);persist();});
  action(bar,"回源","materialSource",()->{MaterialLibraryModel.require(opener!=null&&current.length()>0,"未选资料或来源未接通");JSONObject ref=current.getJSONObject("reference");opener.open(ref.getString("kind"),MaterialLibraryModel.resolve(ref,sourceRows()));});
  if(reader.getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)reader.getParent()).removeView(reader);old.removeView(body);reader.removeAllViews();reader.addView(body);reader.setPadding(dp(8),0,dp(8),0);
  readerHost.addView(reader,new LayoutParams(-1,0,1));editorScroll=new ScrollView(getContext());LinearLayout editor=layout(editorScroll);
  for(EditText input:new EditText[]{category,tags,notes}){old.removeView(input);editor.addView(input);input.setMinimumHeight(dp(48));}
  category.setSingleLine(true);tags.setSingleLine(true);notes.setMaxLines(5);notes.setVerticalScrollBarEnabled(true);
  for(int n=old.getChildCount()-1;n>=0;n--){View v=old.getChildAt(n);if(v instanceof Button){String text=((Button)v).getText().toString();if(text.equals("保存人工分类")||text.equals("放弃未保存分类")){old.removeView(v);editor.addView(v,new LayoutParams(-1,dp(48)));}}}
  readerHost.addView(editorScroll,new LayoutParams(-1,0,1));
  LinearLayout panel=new LinearLayout(getContext());panel.setOrientation(VERTICAL);panel.setVisibility(GONE);
  for(Spinner spinner:filters.values()){int at=mainContent.indexOfChild(spinner);View label=mainContent.getChildAt(at-1);mainContent.removeView(label);mainContent.removeView(spinner);panel.addView(label);panel.addView(spinner,new LayoutParams(-1,dp(48)));}
  Button toggle=new Button(getContext());toggle.setText("筛选条件");toggle.setOnClickListener(v->panel.setVisibility(panel.getVisibility()==VISIBLE?GONE:VISIBLE));mainContent.addView(toggle,2,new LayoutParams(-1,dp(48)));mainContent.addView(panel,3);
 }
 Button action(LinearLayout row,String label,String tag,Work work){Button b=new Button(getContext());b.setText(label);b.setTag(tag);b.setTextSize(12);b.setPadding(0,0,0,0);row.addView(b,new LayoutParams(0,-1,1));b.setOnClickListener(v->guard(work));return b;}
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 void setEditing(boolean value){editing=value;if(editorScroll!=null){editorScroll.setVisibility(value?VISIBLE:GONE);reader.setVisibility(value?GONE:VISIBLE);}}
 LinearLayout layout(ScrollView s){LinearLayout l=new LinearLayout(getContext());l.setOrientation(VERTICAL);s.addView(l);return l;}
 Button button(LinearLayout l,String text,Work work){Button b=new Button(getContext());b.setText(text);l.addView(b);b.setOnClickListener(v->guard(work));return b;}
 void guard(Work work){try{work.run();}catch(Exception e){status.setText(e.getMessage());}}
 JSONArray sourceRows()throws Exception{MaterialLibraryModel.require(sources!=null,"宿主未提供完整资料源");return sources.current();}
 JSONObject query()throws Exception{JSONObject q=new JSONObject().put("search",search.getText().toString()).put("order",orderSelected==1?"earliest":"latest");for(String k:selected.keySet())q.put(k,selected.get(k));return q;}
 void refresh()throws Exception{JSONArray candidate=MaterialLibraryModel.materials(sourceRows());all=candidate;heads=store.heads();boolean was=loading;loading=true;for(String key:filters.keySet()){TreeSet<String> values=new TreeSet<>();for(int i=0;i<all.length();i++){JSONObject m=all.getJSONObject(i);String value=key.equals("category")?MaterialLibraryModel.obj(heads,MaterialLibraryModel.key(m.getJSONObject("reference"))).optString("category"):m.optString(key);values.add(value.isEmpty()?"未分类":value);}List<String> list=options.get(key);list.clear();list.add("");list.addAll(values);List<String> labels=new ArrayList<>(list);labels.set(0,"全部");filters.get(key).setAdapter(new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_dropdown_item,labels));int index=list.indexOf(selected.get(key));selected.put(key,index<0?"":list.get(index));filters.get(key).setSelection(index<0?0:index);}loading=was;render();}
 void render()throws Exception{matches=MaterialLibraryModel.filter(all,query(),heads);page=Math.max(0,Math.min(page,Math.max(0,(matches.length()-1)/20)));rows.removeAllViews();for(int i=page*20;i<Math.min(matches.length(),(page+1)*20);i++){JSONObject m=matches.getJSONObject(i);button(rows,m.optString("title")+" / "+m.optString("source")+" / "+m.optString("type"),()->choose(m));}previous.setEnabled(page>0);next.setEnabled((page+1)*20<matches.length());status.setText("全量 "+all.length()+" · 匹配 "+matches.length()+" · 第"+(page+1)+"/"+Math.max(1,(matches.length()+19)/20)+"页 · 人工标签不是事实");SourceHandoffPanel.styleTree(rows,dark);}
 JSONArray tagArray()throws Exception{String text=tags.getText().toString();if(text.equals(baseline.optString("tagsText")))return baselineTags;JSONArray a=new JSONArray();if(text.isEmpty())return a;for(String tag:text.split(";",-1))a.put(tag);return a;}
 JSONObject fields()throws Exception{return new JSONObject().put("category",category.getText().toString()).put("tagsText",tags.getText().toString()).put("notes",notes.getText().toString());}
 void choose(JSONObject m)throws Exception{MaterialLibraryModel.require(current.length()==0||EvidenceReviewModel.canonical(fields()).equals(EvidenceReviewModel.canonical(baseline)),"分类有未保存修改；先保存或明确放弃");current=new JSONObject(MaterialLibraryModel.json(m));JSONObject c=MaterialLibraryModel.obj(heads,MaterialLibraryModel.key(m.getJSONObject("reference")));expected=c.optString("id");loading=true;category.setText(c.optString("category"));List<String> ts=new ArrayList<>();JSONArray a=MaterialLibraryModel.arr(c,"tags");for(int i=0;i<a.length();i++)ts.add(a.getString(i));tags.setText(String.join(";",ts));notes.setText(c.optString("notes"));baselineTags=a;baseline=fields();loading=false;body.setText(MaterialLibraryModel.read(current,c));setEditing(false);show(1);persist();}
 void show(int index){view=index;frame.removeAllViews();frame.addView(index==0?main:index==1?(readerHost==null?reader:readerHost):io,new FrameLayout.LayoutParams(-1,-1));SourceHandoffPanel.styleTree(frame,dark);}
 void persist(){if(loading)return;guard(()->revision=store.saveState(saveState(),revision));}
 boolean back(){if(view==0)return false;show(0);persist();return true;}
 void setFileActions(SourceHandoffPanel.Exporter exporter,Runnable chooseImport){this.exporter=exporter;this.chooseImport=chooseImport;}
 void previewImport(String text)throws Exception{JSONObject candidate=store.preview(text);pending=candidate;preview.setText(MaterialLibraryModel.json(pending));show(2);persist();}
 void setDarkTheme(boolean dark){this.dark=dark;SourceHandoffPanel.styleTree(this,dark);}
 JSONObject saveState()throws Exception{return new JSONObject().put("query",query()).put("page",page).put("current",current).put("baseline",baseline).put("baselineTags",baselineTags).put("expectedHead",expected).put("fields",fields()).put("pending",pending).put("view",view).put("listScroll",main.getScrollY()).put("readerScroll",reader.getScrollY()).put("editing",editing);}
 void restoreState(JSONObject s)throws Exception{boolean was=loading;loading=true;JSONObject q=MaterialLibraryModel.obj(s,"query");search.setText(q.optString("search"));for(String k:filters.keySet()){int index=options.get(k).indexOf(q.optString(k));selected.put(k,index<0?"":options.get(k).get(index));filters.get(k).setSelection(index<0?0:index);}orderSelected=q.optString("order").equals("earliest")?1:0;order.setSelection(orderSelected);page=Math.max(0,s.optInt("page"));current=MaterialLibraryModel.obj(s,"current");baseline=MaterialLibraryModel.obj(s,"baseline");baselineTags=MaterialLibraryModel.arr(s,"baselineTags");expected=s.optString("expectedHead");JSONObject f=MaterialLibraryModel.obj(s,"fields");category.setText(f.optString("category"));tags.setText(f.optString("tagsText"));notes.setText(f.optString("notes"));pending=MaterialLibraryModel.obj(s,"pending");body.setText(MaterialLibraryModel.read(current,MaterialLibraryModel.obj(heads,current.length()>0?MaterialLibraryModel.key(current.getJSONObject("reference")):"")));preview.setText(MaterialLibraryModel.json(pending));show(Math.max(0,Math.min(2,s.optInt("view"))));setEditing(s.optBoolean("editing"));loading=was;render();main.post(()->main.scrollTo(0,s.optInt("listScroll")));reader.post(()->reader.scrollTo(0,s.optInt("readerScroll")));}
}


